let brokers = msg.payload;

// se não tiver dados, responde com mensagem de erro
if (!brokers || !Array.isArray(brokers) || brokers.length === 0) {
    msg.headers = { 'content-type': 'text/html; charset=utf-8' };
    msg.payload = `<html><head><meta charset="utf-8"><title>Corretoras</title></head>
        <body><h2>Lista de corretoras</h2><p>Nenhuma corretora encontrada ou erro na API.</p></body></html>`;
    return msg;
}

let rows = brokers.map(b => {
    return `<li>${b.nome_social} - ${b.municipio} / ${b.cnpj}</li>`;
}).join('\n');

msg.headers = { 'content-type': 'text/html; charset=utf-8' };
msg.payload = `
<html>
<head>
  <meta charset="utf-8">
  <title>Corretoras CVM</title>
  <style>
    body{font-family:Arial,Helvetica,sans-serif;padding:20px}
    h1{color:#333}
    ul{list-style:none;padding:0}
    li{padding:6px 0;border-bottom:1px solid #eee}
  </style>
</head>
<body>
  <h1>Lista de Corretoras (CVM)</h1>
  <ul>${rows}</ul>
</body>
</html>`;
return msg;

let dados = msg.payload;


// Função pra impedir o "?" da rota,que resulta no erro "Cannot GET /cep"
const scriptRedirecionamento = `
<script>
    function buscarCep(event) {
        // Impede que o formulário submeta via GET padrão (que adiciona o '?')
        event.preventDefault(); 

        // Pega o valor do input pelo ID
        // O ID 'cep_input_novo' foi usado para evitar conflito com outros IDs, caso existam.
        const cep = document.getElementById('cep_input_novo').value;

        // Validação simples de 8 dígitos numéricos
        if (cep && cep.length === 8 && !isNaN(cep)) {
            // Força o redirecionamento para a URL no formato /cep/VALOR (com a barra /)
            window.location.href = "/cep/" + cep;
        } else {
            alert("Por favor, digite um CEP válido com 8 dígitos.");
        }
    }
</script>
`;

// Se não encontrar o CEP (ou a API der erro)
if (!dados || dados.errors) {
    msg.headers = { 'content-type': 'text/html; charset=utf-8' };
    msg.statusCode = 404;
    let htmlErro = `
    <html>
    <head>
      <meta charset="utf-8">
      <title>Resultado do CEP</title>
      <style>
        body { font-family: Arial, sans-serif; padding: 30px; background: #f8f8f8; }

        .form-container { margin-bottom: 30px; padding: 15px; background: #fff; border-radius: 8px; box-shadow: 0 0 5px rgba(0,0,0,0.1); }
        input[type="text"] { padding: 8px; margin-right: 10px; border: 1px solid #ccc; border-radius: 4px; }
        input[type="submit"] { background-color: #dc3545; color: white; padding: 8px 15px; border: none; border-radius: 4px; cursor: pointer; }
        h2 { color: #dc3545; }
      </style>
    </head>
    <body>
      <div class="form-container">
        <h2>Pesquisar Novo CEP</h2>
                <form onsubmit="buscarCep(event)">
                    <input type="text" id="cep_input_novo" placeholder="Digite o CEP" maxlength="8" required>
          <input type="submit" value="Buscar">
        </form>
      </div>

      <h2>CEP não encontrado ou inválido.</h2>

        ${scriptRedirecionamento}
    </body>
    </html>`;

    msg.payload = htmlErro;
    return msg;
}

// Se encontrar o CCEP 
let html = `
<html>
<head>
  <meta charset="utf-8">
  <title>Resultado do CEP</title>
  <style>
    body { font-family: Arial, sans-serif; padding: 30px; background: #f8f8f8; }
    h1 { color: #333; }
    .form-container { margin-bottom: 30px; padding: 15px; background: #fff; border-radius: 8px; box-shadow: 0 0 5px rgba(0,0,0,0.1); }
    input[type="text"] { padding: 8px; margin-right: 10px; border: 1px solid #ccc; border-radius: 4px; }
    input[type="submit"] { background-color: #007bff; color: white; padding: 8px 15px; border: none; border-radius: 4px; cursor: pointer; }
    .info { margin-top: 20px; background: #fff; padding: 15px; border-radius: 8px; box-shadow: 0 0 5px rgba(0,0,0,0.1); }
    p { margin: 5px 0; }
  </style>
</head>
<body>

  <div class="form-container">
    <h1>Pesquisar Novo CEP</h1>
        <form onsubmit="buscarCep(event)">
            <input type="text" id="cep_input_novo" placeholder="Digite o CEP" maxlength="8" required>
            <input type="submit" value="Buscar">
        </form>
  </div>

  <h1>Resultado da busca para ${dados.cep}</h1>
  <div class="info">
    <p><strong>CEP:</strong> ${dados.cep}</p>
    <p><strong>Rua:</strong> ${dados.street}</p>
    <p><strong>Bairro:</strong> ${dados.neighborhood}</p>
    <p><strong>Cidade:</strong> ${dados.city}</p>
    <p><strong>Estado:</strong> ${dados.state}</p>

    ${scriptRedirecionamento}
</body>
</html>`;

msg.headers = { 'content-type': 'text/html; charset=utf-8' };
msg.statusCode = 200;
msg.payload = html;
return msg;

// Obtém os dados relevantes do resultado da busca de CEP
const dados_originais = msg.payload;

const cep = dados_originais.cep;
const cidade = dados_originais.city;

const notificacao = {
    timestamp: Date.now(),
    servico: "Buscador de CEP",
    status: "SUCESSO",
    dados: {
        cep_buscado: cep,
        cidade_encontrada: cidade
    }
};

const msg_mqtt = {}; //Saída 2 "Mqtt",saída 1 "fazer visual do Cep"
msg_mqtt.topic = "d3v/projeto_brasilapi/cep_buscas";
msg_mqtt.payload = JSON.stringify(notificacao);

return [msg, msg_mqtt];
